const KEY_PREFIX='studyhelper_v6_';
let authReady=false;
let authMode='demo';
let authClient=null;
let sessionUser=null;
let setupAvailable=false;
function storageKey(){return KEY_PREFIX+(sessionUser?.id||'demo')}

const DB_NAME='studyquest_files';
const DB_STORE='textbooks';
const seed={
  courses:[
    {id:'cs220',name:'Data Structures',code:'CS 220',mastery:74,items:24,weak:'Recursion, graph traversal'},
    {id:'math210',name:'Discrete Mathematics',code:'MATH 210',mastery:61,items:19,weak:'Proof techniques'},
    {id:'psy101',name:'Psychology',code:'PSY 101',mastery:88,items:31,weak:'Memory models'}
  ],
  sets:[
    {id:'set1',courseId:'cs220',title:'Data Structures Essentials',questions:[
      {q:'Which structure uses LIFO order?',answers:['Queue','Stack','Heap','Graph'],correct:1,explain:'A stack is last-in, first-out (LIFO).',concept:'Stacks'},
      {q:'What is the average-case lookup complexity of a well-designed hash table?',answers:['O(1)','O(log n)','O(n)','O(n log n)'],correct:0,explain:'Hashing aims for constant-time average lookup when collisions are controlled.',concept:'Hash Tables'},
      {q:'Which traversal visits a node before its descendants?',answers:['Postorder','Preorder','Inorder','Breadth-first'],correct:1,explain:'Preorder processes the current node before recursively visiting descendants.',concept:'Tree Traversal'},
      {q:'What does Big-O primarily describe?',answers:['Exact runtime','Asymptotic growth','Memory address','Compiler version'],correct:1,explain:'Big-O describes an upper bound on how resource usage grows as input size increases.',concept:'Big-O'}
    ]},
    {id:'set2',courseId:'math210',title:'Induction & Proofs',questions:[
      {q:'What is the first step of a standard proof by induction?',answers:['Inductive hypothesis','Base case','Contradiction','Counterexample'],correct:1,explain:'You establish that the statement is true for the initial value.',concept:'Induction'},
      {q:'In the inductive step, what do you assume?',answers:['The conclusion is false','The statement holds for k','All numbers are prime','Nothing'],correct:1,explain:'The inductive hypothesis assumes the statement holds for an arbitrary k.',concept:'Induction'}
    ]}
  ],
  books:[],
  requests:[],
  progress:{streak:4,xp:1840,mastery:74,questionsAnswered:128,bestStreak:9,concepts:{'Big-O':92,'Stacks':84,'Tree Traversal':76,'Hash Tables':61,'Induction':58}},
  settings:{name:'Mic',avatar:'M',bio:'College student building a stronger study routine',major:'',school:'',userId:'user_mic'},
  users:[{id:'user_mic',name:'Mic',email:'mic@studyhelper.local',role:'admin',status:'active',created:'Local prototype'}],
  view:'dashboard'
};
let state=load();
const view=document.getElementById('view'), title=document.getElementById('page-title');
function load(){try{const saved=JSON.parse(localStorage.getItem(storageKey())||'{}');return {...structuredClone(seed),...saved,settings:{...structuredClone(seed.settings),...(saved.settings||{})},progress:{...structuredClone(seed.progress),...(saved.progress||{}),concepts:{...structuredClone(seed.progress.concepts),...((saved.progress||{}).concepts||{})}},users:Array.isArray(saved.users)?saved.users:structuredClone(seed.users),view:saved.view||'dashboard'}}catch{return structuredClone(seed)}}
function save(){const clean={...state,books:state.books.map(({data,...b})=>b)};localStorage.setItem(storageKey(),JSON.stringify(clean))}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(DB_STORE))r.result.createObjectStore(DB_STORE)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function putBookFile(id,blob){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(blob,id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function getBookFile(id){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly');const r=tx.objectStore(DB_STORE).get(id);r.onsuccess=()=>{db.close();resolve(r.result||null)};r.onerror=()=>{db.close();reject(r.error)}})}
async function deleteBookFile(id){if(!id)return;try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).delete(id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}catch{}}
function uid(prefix='id'){return prefix+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function courseById(id){return state.courses.find(c=>c.id===id)}
function setAuthChrome(locked){document.body.classList.toggle('auth-locked',locked)}
function authScreen(){
  const setupBlock=setupAvailable?`<div class="auth-setup-card"><div class="eyebrow">FIRST-TIME SETUP</div><h3>Set up the administrator</h3><p class="muted">This appears only while the Supabase project has no users.</p><button class="secondary" id="setupAdmin">Create first administrator</button></div>`:'';
  return `<div class="auth-screen"><div class="auth-card"><div class="brand"><div class="brand-mark">SH</div><div><div class="brand-name">StudyHelper</div><div class="brand-sub">College study + games</div></div></div><div style="margin-top:26px"><div class="eyebrow">SECURE STUDY SPACE</div><h2>Sign in to StudyHelper</h2><p class="muted">Your courses, textbooks, progress, and profile stay behind your account.</p><div class="field"><label>Email</label><input id="authEmail" type="email" autocomplete="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="authPassword" type="password" autocomplete="current-password" placeholder="Your password"></div><button class="primary" id="authSubmit" style="width:100%">Sign in</button><div class="auth-secondary"><button class="ghost" id="requestAccessToggle">Request access</button><button class="ghost" id="demoMode">Local demo</button></div><div id="authError"></div>${setupBlock}<div class="auth-note">There is no public account creation. New users must be approved by an administrator.</div></div></div></div>`
}
async function openFirstAdminSetup(){
  showModal(`<div class="eyebrow">FIRST-TIME SETUP</div><h2>Create the first administrator</h2><p class="muted">This can only succeed when the Supabase project has no existing users. The setup key is configured in Vercel and is never stored in the browser.</p><label class="form-label">Setup key</label><input id="setupKey" type="password" autocomplete="off" placeholder="Vercel STUDYHELPER_SETUP_KEY"><label class="form-label">Administrator name</label><input id="setupName" maxlength="60" placeholder="Your name"><label class="form-label">Email</label><input id="setupEmail" type="email" maxlength="160" placeholder="admin@example.com"><label class="form-label">Password</label><input id="setupPassword" type="password" autocomplete="new-password" minlength="8" placeholder="At least 8 characters"><label class="form-label">Confirm password</label><input id="setupPassword2" type="password" autocomplete="new-password" minlength="8" placeholder="Repeat password"><div id="setupError"></div><div class="modal-actions"><button class="ghost" id="cancelSetup">Cancel</button><button class="primary" id="createFirstAdmin">Create administrator</button></div>`);
  document.getElementById('cancelSetup').onclick=closeModal;
  document.getElementById('createFirstAdmin').onclick=async()=>{
    const key=document.getElementById('setupKey').value.trim(),name=document.getElementById('setupName').value.trim(),email=document.getElementById('setupEmail').value.trim(),password=document.getElementById('setupPassword').value,password2=document.getElementById('setupPassword2').value,err=document.getElementById('setupError');
    err.innerHTML='';
    if(!key||!name||!email||!password){err.innerHTML='<div class="auth-error">All fields are required.</div>';return}
    if(password.length<8){err.innerHTML='<div class="auth-error">Password must be at least 8 characters.</div>';return}
    if(password!==password2){err.innerHTML='<div class="auth-error">Passwords do not match.</div>';return}
    try{
      const r=await fetch('/api/setup-first-admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({setupKey:key,name,email,password})});
      const d=await r.json(); if(!r.ok) throw new Error(d.error||'Could not create the administrator.');
      closeModal(); setupAvailable=false; renderAuthOnly(); showModal(`<div class="score">✓</div><h2>Administrator created</h2><p class="muted">Your administrator account is ready. Sign in with the email and password you just created.</p><button class="primary" id="setupDone">Back to sign in</button>`); document.getElementById('setupDone').onclick=closeModal;
    }catch(e){err.innerHTML='<div class="auth-error">'+esc(e.message||'Could not create the administrator.')+'</div>'}
  };
}
function bindAuth(){
  const requestBtn=document.getElementById('requestAccessToggle'); if(requestBtn)requestBtn.onclick=()=>showAccessRequest();
  const demo=document.getElementById('demoMode'); if(demo)demo.onclick=()=>{authMode='demo';sessionUser={id:'demo',name:'Mic',email:'demo@studyhelper.local',role:'admin',status:'active'};state=load();authReady=true;setAuthChrome(false);render()};
  const setup=document.getElementById('setupAdmin'); if(setup)setup.onclick=openFirstAdminSetup;
  const submit=document.getElementById('authSubmit'); if(submit)submit.onclick=async()=>{const email=document.getElementById('authEmail').value.trim(),password=document.getElementById('authPassword').value,err=document.getElementById('authError');err.innerHTML='';if(!email||!password){err.innerHTML='<div class="auth-error">Please enter your email and password.</div>';return}try{if(!authClient)throw new Error('Cloud authentication is not configured. Use Local demo or connect Supabase.');const {data,error}=await authClient.auth.signInWithPassword({email,password});if(error)throw error;await finishCloudSession(data.session)}catch(e){err.innerHTML='<div class="auth-error">'+esc(e.message||'Unable to sign in.')+'</div>'}};
}
function renderAuthOnly(){authReady=false;sessionUser=null;state=structuredClone(seed);setAuthChrome(true);if(title)title.textContent='Sign in';if(view)view.innerHTML=authScreen();closeModal();bindAuth()}
async function refreshSetupAvailability(){setupAvailable=false;try{const r=await fetch('/api/setup-status',{cache:'no-store'});if(r.ok){const d=await r.json();setupAvailable=Boolean(d.setupAvailable)}}catch{}return setupAvailable}

function showAccessRequest(){showModal(`<div class="eyebrow">REQUEST ACCESS</div><h2>Ask to join StudyHelper</h2><p class="muted">An administrator must approve your request before an account can be created. You do not set a password here.</p><label class="form-label">Name</label><input id="requestName" maxlength="60" placeholder="Your name"><label class="form-label">Email</label><input id="requestEmail" type="email" maxlength="160" placeholder="you@example.com"><label class="form-label">Major / program <span class="muted">(optional)</span></label><input id="requestMajor" maxlength="100" placeholder="e.g. Computer Science"><label class="form-label">Why are you requesting access? <span class="muted">(optional)</span></label><textarea id="requestMessage" rows="4" maxlength="500" placeholder="Class, study group, or reason for using StudyHelper"></textarea><div id="requestError"></div><div class="modal-actions"><button class="ghost" id="cancelRequest">Cancel</button><button class="primary" id="sendRequest">Submit request</button></div>`);document.getElementById('cancelRequest').onclick=closeModal;document.getElementById('sendRequest').onclick=submitAccessRequest}
async function submitAccessRequest(){const name=document.getElementById('requestName').value.trim(),email=document.getElementById('requestEmail').value.trim(),major=document.getElementById('requestMajor').value.trim(),message=document.getElementById('requestMessage').value.trim(),err=document.getElementById('requestError');err.innerHTML='';if(!name||!email){err.innerHTML='<div class="auth-error">Name and email are required.</div>';return}try{if(authMode==='cloud'&&authClient){const {error}=await authClient.from('access_requests').insert({name,email,major,message,status:'pending'});if(error){if(error.code==='23505')throw new Error('There is already a pending request for that email.');throw error}}else{state.requests=Array.isArray(state.requests)?state.requests:[];if(state.requests.some(r=>r.email.toLowerCase()===email.toLowerCase()&&r.status==='pending'))throw new Error('There is already a pending request for that email.');state.requests.push({id:uid('req'),name,email,major,message,status:'pending',created:new Date().toISOString()});save()}closeModal();showModal(`<div class="score">✓</div><h2>Request submitted</h2><p class="muted">An administrator will review your request. Once approved, you will receive the account invitation.</p><button class="primary" id="requestDone">Back to sign in</button>`);document.getElementById('requestDone').onclick=closeModal}catch(e){err.innerHTML='<div class="auth-error">'+esc(e.message||'Could not submit request.')+'</div>'}}
async function finishCloudSession(session){sessionUser={id:session.user.id,name:session.user.user_metadata?.name||session.user.email?.split('@')[0]||'Student',email:session.user.email||'',role:'student',status:'active'};const {data:profile}=await authClient.from('profiles').select('*').eq('id',session.user.id).single();if(profile){sessionUser={...sessionUser,...profile}};if(sessionUser.status==='disabled'){await authClient.auth.signOut();throw new Error('This StudyHelper account is disabled.')}state=load();if(sessionUser.role==='admin'){const {data:profiles}=await authClient.from('profiles').select('id,name,email,role,status,created_at').order('created_at',{ascending:true});if(profiles)state.users=profiles.map(u=>({...u,created:u.created_at||''}));}else{state.users=[{id:sessionUser.id,name:sessionUser.name,email:sessionUser.email,role:sessionUser.role,status:sessionUser.status,created:sessionUser.created_at||''}];}state.settings={...state.settings,name:sessionUser.name,email:sessionUser.email,userId:sessionUser.id};save();authReady=true;setAuthChrome(false);render()}
async function bootAuth(){
  setAuthChrome(true);
  await refreshSetupAvailability();
  try{const res=await fetch('/api/config',{cache:'no-store'});if(!res.ok)throw new Error('Cloud authentication service returned HTTP '+res.status+'.');const cfg=await res.json();if(cfg.configured&&window.supabase){authMode='cloud';authClient=window.supabase.createClient(cfg.url,cfg.publishableKey||cfg.anonKey);const {data}=await authClient.auth.getSession();if(data.session){await finishCloudSession(data.session);return}renderAuthOnly();return}}catch(e){renderAuthOnly();const err=document.getElementById('authError');if(err)err.innerHTML='<div class="auth-error">'+esc(e.message||'Cloud authentication is not configured.')+'</div>';return}
  authMode='demo';sessionUser={id:'demo',name:'Mic',email:'demo@studyhelper.local',role:'admin',status:'active'};state=load();authReady=true;setAuthChrome(false);render();
}
async function logout(){
  try{if(authMode==='cloud'&&authClient)await authClient.auth.signOut()}catch{}
  try{sessionStorage.clear()}catch{}
  sessionUser=null;authReady=false;closeModal();renderAuthOnly();
}
function render(){if(!authReady){renderAuthOnly();return}setAuthChrome(false);const pages={dashboard:dashboard,courses:coursesView,textbooks:textbooksView,games:gamesView,practice:practiceView,progress:progressView,profile:profileView,settings:settingsView,admin:adminView};title.textContent=state.view[0].toUpperCase()+state.view.slice(1);view.innerHTML=(pages[state.view]||dashboard)();bind();updateNav()}
function updateNav(){document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view))}
function dashboard(){const p=state.progress;return `<div class="content"><div class="hero"><div><div class="eyebrow" style="color:#b9b4ff">WELCOME BACK</div><h2>Turn class material into a game you can master.</h2><p>StudyHelper connects your courses, textbooks, practice sessions, and games so your weakest concepts rise to the top.</p></div><div class="hero-actions"><button class="primary" data-action="practice">Start practice</button><button class="ghost" data-action="game">Play a game</button></div></div><div class="grid grid-4 stats"><div class="stat"><div class="label">Current streak</div><div class="value">${p.streak} days</div></div><div class="stat"><div class="label">XP earned</div><div class="value">${p.xp.toLocaleString()}</div></div><div class="stat"><div class="label">Overall mastery</div><div class="value">${p.mastery}%</div></div><div class="stat"><div class="label">Questions answered</div><div class="value">${p.questionsAnswered}</div></div></div><div class="section"><div class="section-head"><h3>Your courses</h3><button class="secondary" data-action="courses">View all</button></div><div class="grid grid-3">${state.courses.map(courseCard).join('')}</div></div><div class="section"><div class="section-head"><h3>Continue studying</h3><span class="muted">Weak areas first</span></div><div class="grid grid-2">${Object.entries(p.concepts).sort((a,b)=>a[1]-b[1]).slice(0,4).map(([name,val])=>`<div class="card"><div class="row"><strong>${esc(name)}</strong><span class="pill orange">${val}%</span></div><div class="muted">Suggested next: ${val<65?'Review + apply':val<80?'Practice':'Challenge'}</div><div class="progress"><span style="width:${val}%"></span></div><button class="secondary" data-concept="${esc(name)}">Practice concept</button></div>`).join('')}</div></div></div>`}
function courseCard(c){return `<div class="card course-card"><div class="row"><div class="course-icon">${esc(c.code.slice(0,2))}</div><span class="pill">${c.mastery}% mastery</span></div><div><strong>${esc(c.name)}</strong><div class="muted">${esc(c.code)} - ${c.items} study items</div></div><div class="progress"><span style="width:${c.mastery}%"></span></div><div class="muted">Needs work: ${esc(c.weak||'Build a study set')}</div><div class="card-actions"><button class="primary" data-course="${c.id}" data-mode="practice">Practice</button><button class="ghost" data-course="${c.id}" data-mode="game">Game</button></div></div>`}
function coursesView(){return `<div class="content"><div class="row"><div><p class="muted">Build a course-specific knowledge base.</p></div><button class="primary" data-action="new-course">+ New course</button></div><div class="grid grid-3" style="margin-top:18px">${state.courses.map(courseCard).join('')}</div><div class="section card"><div class="section-head"><h3>Your study sets</h3><button class="secondary" data-action="new-set">+ New set</button></div>${state.sets.map(s=>`<div class="book-row"><div class="book-icon">Q</div><div class="meta"><strong>${esc(s.title)}</strong><div class="muted">${esc(courseById(s.courseId)?.name||'Unassigned')} - ${s.questions.length} questions</div></div><button class="secondary" data-set="${s.id}">Practice</button><button class="ghost" data-edit-set="${s.id}">Edit</button></div>`).join('')}</div></div>`}
function textbooksView(){return `<div class="content"><div class="hero" style="background:linear-gradient(135deg,#1c2435,#25364d)"><div><div class="eyebrow" style="color:#b7cadf">TEXTBOOK LIBRARY</div><h2>Keep your books next to your study games.</h2><p>PDFs are saved privately in your browser for this offline-capable build. The cloud version can move the same library to private storage.</p></div><div class="hero-actions"><button class="primary" data-action="upload">Upload textbook</button></div></div><div class="section"><div class="dropzone"><strong>Drop a PDF here</strong><div class="muted">or choose a PDF from your computer</div><label for="bookInput">Choose PDF</label><input id="bookInput" type="file" accept="application/pdf,.pdf" /></div><div class="book-list">${state.books.length?state.books.map((b,i)=>`<div class="book-row"><div class="book-icon">PDF</div><div class="meta"><strong>${esc(b.name)}</strong><div class="muted">${b.size} - ${b.when}</div></div><button class="secondary" data-book="${i}">Open</button><button class="ghost" data-remove-book="${i}">Remove</button></div>`).join(''):`<div class="empty card"><strong>No textbooks yet</strong><div class="muted">Upload a PDF and it will remain available on this browser.</div></div>`}</div></div><div class="section"><div class="notice"><strong>Privacy:</strong> this build keeps the PDF itself in IndexedDB on your device. It does not upload it to a third party.</div></div></div>`}
function gamesView(){const modes=[
  {id:'Quest Rush',icon:'⚡',tag:'SPEED',title:'Quest Rush',desc:'60-second solo sprint. Build a streak to multiply your XP.',rules:['60-second timer','3 points for each correct answer','Streak bonus every 3 answers'],action:'Start sprint'},
  {id:'Campus Clash',icon:'🏫',tag:'VERSUS',title:'Campus Clash',desc:'Turn your study set into a competitive room with simulated rivals now and real multiplayer later.',rules:['8-round match','Score changes each round','Comeback bonus for answering late'],action:'Enter arena'},
  {id:'Boss Battle',icon:'👾',tag:'BOSS',title:'Boss Battle',desc:'Hard application questions where every mistake costs a life.',rules:['3 lives','Application-focused prompts','Beat the boss before time runs out'],action:'Fight boss'}
];return `<div class="content"><div class="card game-banner"><div class="row"><div><div class="eyebrow">GAME AREA</div><h2 style="margin:5px 0">Choose your challenge</h2><div class="muted">Different rules, different skills. Pick the way you want to learn.</div></div><button class="primary" data-action="host">Host Campus Clash</button></div></div><div class="grid grid-3" style="margin-top:18px">${modes.map(g=>`<div class="card game-card"><div class="game-icon game-icon-large">${g.icon}</div><div class="row"><strong>${g.title}</strong><span class="pill">${g.tag}</span></div><div class="muted">${g.desc}</div><div class="game-rules">${g.rules.map(r=>`<div>• ${r}</div>`).join('')}</div><div class="card-actions"><button class="primary" data-game-mode="${g.id}">${g.action}</button><button class="ghost" data-action="course-pick">Choose content</button></div></div>`).join('')}</div><div class="section grid grid-2"><div class="card"><div class="eyebrow">JOIN A FRIEND</div><h3>Enter a game code</h3><div style="display:flex;gap:8px;margin-top:12px"><input id="joinCode" maxlength="6" placeholder="e.g. 482731" style="flex:1;padding:12px;border:1px solid var(--line);border-radius:12px"/><button class="primary" id="joinBtn">Join game</button></div><div class="muted" style="margin-top:10px">Cloud multiplayer will plug into this same room flow later.</div></div><div class="card"><div class="eyebrow">HOW TO WIN</div><h3>Play to learn</h3><p class="muted">Games reward recall, accuracy, speed, and application rather than button mashing. Your results update the same mastery system used by Practice.</p></div></div></div>`}

function practiceView(){const weak=Object.entries(state.progress.concepts).sort((a,b)=>a[1]-b[1]).slice(0,5);return `<div class="content"><div class="hero"><div><div class="eyebrow" style="color:#b9b4ff">FOCUS SESSION</div><h2>Practice weak areas first.</h2><p>Questions are selected from your saved study sets, with lower-mastery concepts prioritized.</p></div><div class="hero-actions"><button class="primary" data-action="quiz">Start 5-question round</button><button class="ghost" data-action="new-set">Build questions</button></div></div><div class="section"><div class="grid grid-3">${[['Recall','Definitions and core facts'],['Apply','Use concepts in new scenarios'],['Explain','Show why an answer is correct']].map(x=>`<div class="card"><strong>${x[0]}</strong><div class="muted">${x[1]}</div></div>`).join('')}</div></div><div class="section card"><div class="section-head"><h3>Current weak concepts</h3><span class="muted">${weak.length} prioritized</span></div>${weak.map(([n,v])=>`<div class="book-row"><div class="meta"><strong>${esc(n)}</strong><div class="progress"><span style="width:${v}%"></span></div></div><span class="pill orange">${v}%</span></div>`).join('')}</div></div>`}
function progressView(){const p=state.progress;return `<div class="content"><div class="grid grid-3"><div class="stat"><div class="label">Overall mastery</div><div class="value">${p.mastery}%</div></div><div class="stat"><div class="label">This week</div><div class="value">+11%</div></div><div class="stat"><div class="label">Best streak</div><div class="value">${p.bestStreak} days</div></div></div><div class="section card"><div class="section-head"><h3>Concept mastery</h3><span class="muted">Updated after every session</span></div><table class="table"><thead><tr><th>Concept</th><th>Mastery</th><th>Next action</th></tr></thead><tbody>${Object.entries(p.concepts).sort((a,b)=>a[1]-b[1]).map(([name,val])=>`<tr><td><strong>${esc(name)}</strong></td><td>${val}%</td><td><button class="secondary" data-concept="${esc(name)}">Practice</button></td></tr>`).join('')}</tbody></table></div></div>`}

function currentUser(){return sessionUser||state.users.find(u=>u.id===state.settings.userId)||state.users[0]||{id:'local',name:state.settings.name,email:'',role:'student',status:'active'}}
function isAdmin(){return currentUser().role==='admin'&&currentUser().status!=='disabled'}
function settingsView(){return `<div class="content"><div class="hero"><div><div class="eyebrow" style="color:#b9b4ff">SETTINGS & DATA</div><h2>Control your StudyHelper data.</h2><p>Manage your local progress, create backups, and keep your study content under your control.</p></div><button class="primary" data-action="export-data">Export backup</button></div><div class="section grid grid-2"><div class="card"><div class="eyebrow">SAFE RESET</div><h3>Reset study progress</h3><p class="muted">Keeps your courses, study sets, textbooks, and profile. Clears XP, streaks, question counts, and concept mastery.</p><button class="secondary" data-action="reset-progress">Reset progress</button></div><div class="card"><div class="eyebrow">BACKUP</div><h3>Restore a backup</h3><p class="muted">Import a StudyHelper JSON backup created on this device. Textbook PDF files are not included in the JSON backup.</p><label for="backupInput" class="secondary" style="display:inline-block;cursor:pointer">Choose backup</label><input id="backupInput" type="file" accept="application/json,.json" style="display:none"></div><div class="card"><div class="eyebrow">DANGER ZONE</div><h3>Delete study data</h3><p class="muted">Deletes courses, study sets, progress, and profile data from this browser. Your PDFs must be removed separately.</p><button class="ghost" data-action="delete-data" style="color:#b42318">Delete all study data</button></div><div class="card"><div class="eyebrow">ACCOUNT</div><h3>Current account</h3><p class="muted"><strong>${esc(currentUser().name)}</strong><br>${esc(currentUser().email||'Local account')} · ${esc(currentUser().role)}</p><button class="secondary" data-action="edit-profile">Edit profile</button></div></div><div class="section"><div class="notice"><strong>Important:</strong> this browser build uses local storage. Admin controls are functional for this prototype, but they are not a security boundary. The cloud version will enforce roles on the server.</div></div></div>`}
async function refreshAdminData(){if(!isAdmin()||authMode!=='cloud'||!authClient)return;try{const token=(await authClient.auth.getSession()).data.session?.access_token;if(!token)return;const r=await fetch('/api/admin-requests',{headers:{Authorization:`Bearer ${token}`}});const d=await r.json();if(r.ok){state.requests=d.requests||[];const res=await authClient.from('profiles').select('id,name,email,role,status,created_at').order('created_at',{ascending:true});if(!res.error&&res.data)state.users=res.data.map(u=>({...u,created:u.created_at||''}));save();render()}}catch{}}
async function handleRequestDecision(id,action){if(!isAdmin())return;try{if(authMode==='cloud'){const token=(await authClient.auth.getSession()).data.session?.access_token;const r=await fetch('/api/admin-requests',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({requestId:id,action})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not update request.');state.requests=state.requests.map(x=>x.id===id?{...x,...d.request}:x);if(action==='approve'&&d.user)state.users.push(d.user)}else{const req=state.requests.find(x=>x.id===id);if(!req)return;if(action==='approve'){req.status='approved';req.reviewed=new Date().toISOString();state.users.push({id:uid('user'),name:req.name,email:req.email,role:'student',status:'active',created:new Date().toLocaleDateString()})}else{req.status='denied';req.reviewed=new Date().toISOString()}}save();render()}catch(e){alert(e.message)}}
function adminView(){if(!isAdmin())return `<div class="content"><div class="card"><h2>Admin access required</h2><p class="muted">Your current account does not have administrator access.</p></div></div>`;const active=state.users.filter(u=>u.status!=='disabled').length;const pending=(state.requests||[]).filter(r=>r.status==='pending');return `<div class="content"><div class="hero"><div><div class="eyebrow" style="color:#ffcf8a">ADMIN CONSOLE</div><h2>Manage StudyHelper accounts.</h2><p>Only administrators can create accounts, approve requests, change roles, disable access, or delete users.</p></div><button class="primary" data-action="new-user">+ Add account</button></div><div class="grid grid-4 stats"><div class="stat"><div class="label">Accounts</div><div class="value">${state.users.length}</div></div><div class="stat"><div class="label">Active</div><div class="value">${active}</div></div><div class="stat"><div class="label">Pending requests</div><div class="value">${pending.length}</div></div><div class="stat"><div class="label">Study sets</div><div class="value">${state.sets.length}</div></div></div><div class="section card"><div class="section-head"><h3>Access requests</h3><button class="secondary" data-action="refresh-requests">Refresh</button></div>${pending.length?`<div class="book-list">${pending.map(r=>`<div class="book-row"><div class="avatar">${esc(initials(r.name).slice(0,3))}</div><div class="meta"><strong>${esc(r.name)}</strong><div class="muted">${esc(r.email)}${r.major?' · '+esc(r.major):''}</div><div class="muted" style="margin-top:4px">${esc(r.message||'No message')} · ${new Date(r.created_at||r.created).toLocaleString()}</div></div><button class="secondary" data-request-approve="${r.id}">Approve</button><button class="ghost" data-request-deny="${r.id}" style="color:#b42318">Deny</button></div>`).join('')}</div>`:'<div class="empty-state"><strong>No pending requests</strong><p class="muted">New requests will appear here for review.</p></div>'}</div><div class="section card"><div class="section-head"><h3>Accounts</h3><span class="muted">Admin-controlled</span></div><div class="book-list">${state.users.map(u=>`<div class="book-row"><div class="avatar">${esc(initials(u.name).slice(0,3))}</div><div class="meta"><strong>${esc(u.name)}</strong><div class="muted">${esc(u.email||'No email')} · ${esc(u.role)} · ${esc(u.status)}</div></div>${u.id!==state.settings.userId?`<button class="secondary" data-user-role="${u.id}">${u.role==='admin'?'Make student':'Make admin'}</button><button class="ghost" data-user-status="${u.id}">${u.status==='disabled'?'Enable':'Disable'}</button><button class="ghost" data-user-delete="${u.id}" style="color:#b42318">Delete</button>`:`<span class="pill">Current account</span>`}</div>`).join('')}</div></div><div class="section grid grid-2"><div class="card"><div class="eyebrow">CONTENT TOTALS</div><div class="grid grid-2" style="margin-top:14px"><div><div class="label">Courses</div><strong>${state.courses.length}</strong></div><div><div class="label">Questions</div><strong>${getQuestions().length}</strong></div><div><div class="label">Textbooks</div><strong>${state.books.length}</strong></div><div><div class="label">XP</div><strong>${state.progress.xp.toLocaleString()}</strong></div></div></div><div class="card"><div class="eyebrow">ADMIN SAFETY</div><p class="muted">Cloud mode uses server-authorized administrator checks. The Supabase service-role key never reaches the browser.</p></div></div></div>`}
async function showNewUser(){if(!isAdmin())return;showModal(`<div class="eyebrow">NEW ACCOUNT</div><h2>Add a StudyHelper account</h2><label class="form-label">Display name</label><input id="userName" maxlength="40" placeholder="Student name"><label class="form-label">Email</label><input id="userEmail" maxlength="120" placeholder="student@example.com" type="email"><label class="form-label">Temporary password</label><input id="userPassword" minlength="8" type="password" placeholder="At least 8 characters"><label class="form-label">Role</label><select id="userRole"><option value="student">Student</option><option value="admin">Administrator</option></select><div class="notice" style="margin-top:12px"><strong>${authMode==='cloud'?'Secure cloud account':'Local demo account'}</strong><br>${authMode==='cloud'?'The password is sent only to the protected Vercel server function and Supabase Auth.':'Demo accounts are stored only in this browser and are not real login accounts.'}</div><div id="newUserError"></div><div class="modal-actions"><button class="ghost" id="cancelUser">Cancel</button><button class="primary" id="saveUser">Create account</button></div>`);document.getElementById('cancelUser').onclick=closeModal;document.getElementById('saveUser').onclick=async()=>{const name=document.getElementById('userName').value.trim(),email=document.getElementById('userEmail').value.trim(),password=document.getElementById('userPassword').value,role=document.getElementById('userRole').value,err=document.getElementById('newUserError');err.innerHTML='';if(!name||!email||!password){err.innerHTML='<div class="auth-error">Name, email, and password are required.</div>';return}if(password.length<8){err.innerHTML='<div class="auth-error">Password must be at least 8 characters.</div>';return}try{if(authMode==='cloud'){const token=(await authClient.auth.getSession()).data.session?.access_token;if(!token)throw new Error('Your session has expired. Please sign in again.');const r=await fetch('/api/admin-create-user',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({name,email,password,role})});const data=await r.json();if(!r.ok)throw new Error(data.error||'Could not create account.');state.users.push(data.user);}else{if(state.users.some(u=>u.email.toLowerCase()===email.toLowerCase()))throw new Error('An account with that email already exists.');state.users.push({id:uid('user'),name,email,role,status:'active',created:new Date().toLocaleDateString()});}save();closeModal();render()}catch(e){err.innerHTML='<div class="auth-error">'+esc(e.message||'Could not create account.')+'</div>'}}}
function getQuestions(setId=null,concept=null){let qs=[];state.sets.forEach(s=>s.questions.forEach(q=>qs.push({...q,setId:s.id,setTitle:s.title})));if(setId)qs=qs.filter(q=>q.setId===setId);if(concept)qs=qs.filter(q=>q.concept.toLowerCase()===concept.toLowerCase());return qs}
function quiz(setId=null,mode='Recall',concept=null,type='multiple'){let qs=getQuestions(setId,concept);if(!qs.length){showModal('<h2>No questions yet</h2><p class="muted">Create a study set and add questions before starting a round.</p><button class="primary" id="goSets">Create study set</button>');document.getElementById('goSets').onclick=()=>{closeModal();showNewSet()};return}qs.sort((a,b)=>(state.progress.concepts[a.concept]||50)-(state.progress.concepts[b.concept]||50));qs=qs.slice(0,6);startGameSession(qs,mode,type)}
function startGameSession(qs,mode,type='multiple'){
  const g={i:0,score:0,streak:0,lives:3,started:Date.now(),timeLeft:mode==='Quest Rush'?60:mode==='Campus Clash'?75:90,round:0,answered:0};
  const finish=(message)=>{state.progress.mastery=Math.round(Object.values(state.progress.concepts).reduce((a,b)=>a+b,0)/Math.max(1,Object.keys(state.progress.concepts).length));save();showModal(`<div class="score">${g.score}</div><h2>${esc(message)}</h2><p class="muted">${g.answered} answered • ${Math.max(0,g.score)} XP earned. Your mastery was updated.</p><button class="primary" id="done">Continue studying</button>`);document.getElementById('done').onclick=()=>{closeModal();state.view='progress';render()}};
  const renderQ=()=>{if(g.i>=qs.length){finish(mode==='Quest Rush'?'Sprint complete!':mode==='Boss Battle'?'Boss defeated!':'Match complete!');return}const q=qs[g.i];const pct=mode==='Boss Battle'?Math.round((g.lives/3)*100):Math.max(8,100-Math.floor((Date.now()-g.started)/1000/g.timeLeft*100));const labels={'Quest Rush':'⚡ Speed sprint','Campus Clash':'🏫 Arena round','Boss Battle':'👾 Boss fight'};let answers=q.answers.map((a,j)=>({text:a,index:j}));if(type==='scramble')answers=answers.sort(()=>Math.random()-.5);showModal(`<div class="game-status"><div><div class="eyebrow">${labels[mode]}</div><strong>${mode==='Boss Battle'?`❤️ ${g.lives} lives`:`Round ${g.i+1} of ${qs.length}`}</strong></div><div class="game-meter"><span style="width:${pct}%"></span></div></div><div class="game-question"><div class="pill">${esc(q.concept||'Concept')} · ${esc(q.difficulty||'medium')}</div><h2>${esc(q.q)}</h2><div class="muted">${type==='truefalse'?'Decide whether the statement is true or false.':type==='recall'?'Recall the answer before revealing the choices.':mode==='Quest Rush'?'Answer quickly for bonus points.':mode==='Campus Clash'?'Correct answers increase your lead.':'Choose carefully. A miss costs a life.'}</div></div><div class="answer-grid">${type==='truefalse'?['True','False'].map((a,j)=>`<button class="answer" data-answer="${j}">${a}</button>`).join(''):answers.map(a=>`<button class="answer" data-answer="${a.index}">${esc(a.text)}</button>`).join('')}</div>${mode==='Campus Clash'?`<div class="rival-line"><span>Rival A: ${Math.max(8,g.round*7+12)} pts</span><span>Rival B: ${Math.max(5,g.round*5+9)} pts</span></div>`:''}`);document.querySelectorAll('.answer').forEach(b=>b.onclick=()=>answer(b,q));if(mode==='Quest Rush')setTimeout(()=>{if(!document.getElementById('modal').classList.contains('hidden')&&g.i<qs.length){g.i=qs.length;finish('Time is up!')}},g.timeLeft*1000)};
  const answer=(btn,q)=>{let selected=Number(btn.dataset.answer);if(type==='truefalse')selected=selected===0?0:1;const correct=selected===q.correct;g.round++;g.answered++;const key=q.concept||q.setTitle;state.progress.questionsAnswered++;if(correct){g.streak++;const bonus=mode==='Quest Rush'?(g.streak>=3?50:30):mode==='Campus Clash'?(20+Math.min(30,g.round*2)):(30+g.streak*5);g.score+=bonus;state.progress.xp+=bonus;state.progress.concepts[key]=Math.min(100,(state.progress.concepts[key]||50)+2)}else{g.streak=0;state.progress.concepts[key]=Math.max(0,(state.progress.concepts[key]||50)-1);if(mode==='Boss Battle')g.lives--}save();showModal(`<div class="score">${correct?`+${mode==='Quest Rush'&&g.streak>=3?50:(mode==='Campus Clash'?(20+Math.min(30,g.round*2)):(30+g.streak*5))} XP`:'Keep going'}</div><h2>${correct?'Correct!':'Not quite.'}</h2><p class="muted">Correct answer: <strong>${esc(q.answers[q.correct])}</strong></p><p class="muted">${esc(q.explain||'Review this concept and try it again later.')}</p><button class="primary" id="nextQ">${mode==='Boss Battle'&&g.lives<=0?'End fight':g.i+1<qs.length?'Next':'Finish'}</button>`);document.getElementById('nextQ').onclick=()=>{if(mode==='Boss Battle'&&g.lives<=0)finish('The boss wins this round.');else{g.i++;renderQ()}}};renderQ();
}
function profileView(){const p=state.settings;return `<div class="content"><div class="hero"><div><div class="eyebrow" style="color:#b9b4ff">YOUR PROFILE</div><h2>Make StudyHelper feel like your study space.</h2><p>Edit your name, avatar, and optional academic details. Your profile is saved to your account in cloud mode, or locally in demo mode.</p></div><button class="primary" data-action="edit-profile">Edit profile</button></div><div class="section grid grid-2"><div class="card"><div class="row"><div class="avatar avatar-large">${esc(p.avatar||initials(p.name))}</div><div style="flex:1"><h3 style="margin:0">${esc(p.name)}</h3><div class="muted">${esc(p.major||'College student')}</div></div></div><p class="muted" style="margin-top:18px">${esc(p.bio||'Add a short bio from Edit profile.')}</p></div><div class="card"><div class="eyebrow">PROFILE STATS</div><div class="grid grid-2" style="margin-top:14px"><div><div class="label">XP</div><strong>${state.progress.xp.toLocaleString()}</strong></div><div><div class="label">Best streak</div><strong>${state.progress.bestStreak} days</strong></div><div><div class="label">Questions</div><strong>${state.progress.questionsAnswered}</strong></div><div><div class="label">Mastery</div><strong>${state.progress.mastery}%</strong></div></div></div></div></div>`}
function initials(name='User'){return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'U'}
function showProfileEditor(){const p=state.settings;showModal(`<div class="eyebrow">PROFILE SETTINGS</div><h2>Edit your profile</h2><label class="form-label">Display name</label><input id="profileName" value="${esc(p.name)}" maxlength="40"><label class="form-label">Avatar letters</label><input id="profileAvatar" value="${esc(p.avatar||initials(p.name))}" maxlength="3"><div class="hint">Use 1–3 letters, or leave it blank to generate initials from your name.</div><label class="form-label">Major / program <span class="muted">(optional)</span></label><input id="profileMajor" value="${esc(p.major||'')}" maxlength="80" placeholder="e.g. Computer Science"><label class="form-label">School <span class="muted">(optional)</span></label><input id="profileSchool" value="${esc(p.school||'')}" maxlength="100" placeholder="College or university"><label class="form-label">Bio <span class="muted">(optional)</span></label><textarea id="profileBio" rows="4" maxlength="240" placeholder="A short description about your study goals.">${esc(p.bio||'')}</textarea><div class="modal-actions"><button class="ghost" id="cancelProfile">Cancel</button><button class="primary" id="saveProfile">Save changes</button></div>`);document.getElementById('cancelProfile').onclick=closeModal;document.getElementById('saveProfile').onclick=()=>{const name=document.getElementById('profileName').value.trim()||'Student';let av=document.getElementById('profileAvatar').value.trim().replace(/[^a-zA-Z0-9]/g,'').slice(0,3).toUpperCase();if(!av)av=initials(name);state.settings={...state.settings,name,avatar:av,major:document.getElementById('profileMajor').value.trim(),school:document.getElementById('profileSchool').value.trim(),bio:document.getElementById('profileBio').value.trim()};const me=currentUser();if(me){me.name=name;me.email=me.email||'local@studyhelper';}save();if(authMode==='cloud'&&authClient&&sessionUser){authClient.from('profiles').update({name,avatar:av,major:state.settings.major,school:state.settings.school,bio:state.settings.bio,updated_at:new Date().toISOString()}).eq('id',sessionUser.id).then(()=>{})};closeModal();render();}};

function showModal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modal').classList.remove('hidden')}
function closeModal(){document.getElementById('modal').classList.add('hidden')}
function showNewCourse(){showModal(`<div class="eyebrow">NEW COURSE</div><h2>Create a course</h2><input id="courseName" placeholder="Course name" style="width:100%;padding:12px;border:1px solid var(--line);border-radius:12px;margin:14px 0 8px"><input id="courseCode" placeholder="Course code (e.g. CS 220)" style="width:100%;padding:12px;border:1px solid var(--line);border-radius:12px"><button class="primary" style="margin-top:12px" id="createCourse">Create course</button>`);document.getElementById('createCourse').onclick=()=>{const n=document.getElementById('courseName').value.trim(),c=document.getElementById('courseCode').value.trim()||'COURSE';if(!n)return;state.courses.push({id:uid('course'),name:n,code:c,mastery:0,items:0,weak:'No study data yet'});save();closeModal();render()}}
function showNewSet(existingId=null){
  const existing=existingId?state.sets.find(s=>s.id===existingId):null;
  const courseOptions=state.courses.map(c=>`<option value="${c.id}" ${existing?.courseId===c.id?'selected':''}>${esc(c.code)} - ${esc(c.name)}</option>`).join('');
  showModal(`<div class="eyebrow">${existing?'EDIT STUDY SET':'NEW STUDY SET'}</div><h2>${existing?'Edit your questions':'Create questions'}</h2><label class="form-label">Course</label><select id="setCourse" style="width:100%;padding:12px;border:1px solid var(--line);border-radius:12px">${courseOptions}</select><label class="form-label">Set title</label><input id="setTitle" value="${esc(existing?.title||'')}" placeholder="Set title"><div id="questionEditor"></div><div class="modal-actions"><button class="secondary" id="addQuestion">+ Add question</button><button class="primary" id="saveSet">${existing?'Save changes':'Save study set'}</button></div>${existing?`<button class="ghost" id="deleteSet" style="margin-top:10px;color:#b42318">Delete study set</button>`:''}`);
  let rows=existing?existing.questions.map(q=>({...q,answers:[...(q.answers||['','','',''])]})):[];
  const redraw=()=>{
    document.getElementById('questionEditor').innerHTML=rows.map((r,idx)=>`<div class="card" style="margin-top:10px"><div class="row"><strong>Question ${idx+1}</strong><button class="ghost" data-del="${idx}">Remove</button></div><label class="form-label">Question</label><textarea data-f="q" data-i="${idx}" rows="2" placeholder="Ask a clear question...">${esc(r.q)}</textarea><label class="form-label">Answer choices</label>${r.answers.map((a,j)=>`<input data-f="a${j}" data-i="${idx}" placeholder="Answer ${j+1}" value="${esc(a)}">`).join('')}<label class="form-label">Correct answer</label><select data-f="correct" data-i="${idx}"><option value="0" ${r.correct===0?'selected':''}>Answer 1</option><option value="1" ${r.correct===1?'selected':''}>Answer 2</option><option value="2" ${r.correct===2?'selected':''}>Answer 3</option><option value="3" ${r.correct===3?'selected':''}>Answer 4</option></select><label class="form-label">Concept</label><input data-f="concept" data-i="${idx}" placeholder="e.g. recursion" value="${esc(r.concept||'')}"><label class="form-label">Explanation <span class="muted">(optional)</span></label><textarea data-f="explain" data-i="${idx}" rows="2" placeholder="Why is this answer correct?">${esc(r.explain||'')}</textarea><label class="form-label">Difficulty</label><select data-f="difficulty" data-i="${idx}"><option value="easy" ${r.difficulty==='easy'?'selected':''}>Easy</option><option value="medium" ${!r.difficulty||r.difficulty==='medium'?'selected':''}>Medium</option><option value="hard" ${r.difficulty==='hard'?'selected':''}>Hard</option></select></div>`).join('')||'<div class="muted" style="margin-top:10px">Add at least one question.</div>';
    document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{rows.splice(Number(b.dataset.del),1);redraw()});
    document.querySelectorAll('#questionEditor [data-f]').forEach(el=>el.oninput=()=>{const r=rows[Number(el.dataset.i)];const f=el.dataset.f;if(f==='q')r.q=el.value;else if(f.startsWith('a'))r.answers[Number(f.slice(1))]=el.value;else r[f]=f==='correct'?Number(el.value):el.value});
  };
  document.getElementById('addQuestion').onclick=()=>{rows.push({q:'',answers:['','','',''],correct:0,explain:'',concept:'',difficulty:'medium'});redraw()};
  document.getElementById('saveSet').onclick=()=>{
    const title=document.getElementById('setTitle').value.trim(),courseId=document.getElementById('setCourse').value;
    if(!title||!rows.length||rows.some(r=>!r.q.trim()||r.answers.some(a=>!a.trim())||!r.concept.trim())){alert('Please complete the set title, every question, all four answers, and a concept.');return}
    if(existing){const oldCourse=courseById(existing.courseId);const newCourse=courseById(courseId);if(oldCourse&&oldCourse.id!==courseId)oldCourse.items=Math.max(0,oldCourse.items-existing.questions.length);existing.courseId=courseId;existing.title=title;existing.questions=rows;newCourse.items=(state.sets.filter(s=>s.courseId===courseId).reduce((n,s)=>n+(s.id===existing.id?0:s.questions.length),0))+rows.length;newCourse.weak=rows[0].concept}else{const s={id:uid('set'),courseId,title,questions:rows};state.sets.unshift(s);const c=courseById(courseId);c.items+=rows.length;c.weak=rows[0].concept}
    save();closeModal();state.view='courses';render();
  };
  const del=document.getElementById('deleteSet');if(del)del.onclick=()=>{if(confirm('Delete this study set and its questions?')){state.sets=state.sets.filter(s=>s.id!==existing.id);const c=courseById(existing.courseId);if(c)c.items=Math.max(0,c.items-existing.questions.length);save();closeModal();render()}};
  redraw();
}
async function openTextbook(i){const b=state.books[i];if(!b){return}let blob=b.data?dataUrlToBlob(b.data):await getBookFile(b.fileId);if(!blob){showModal(`<h2>${esc(b.name)}</h2><p class="muted">The saved PDF file is unavailable in this browser. Please upload it again.</p>`);return}const url=URL.createObjectURL(blob);showModal(`<div class="row"><div><div class="eyebrow">TEXTBOOK READER</div><h2 style="margin:5px 0">${esc(b.name)}</h2></div><button class="secondary" id="bookPractice">Study this book</button></div><div style="height:65vh;margin-top:12px;border:1px solid var(--line);border-radius:12px;overflow:hidden"><iframe title="Textbook reader" src="${url}" style="width:100%;height:100%;border:0"></iframe></div>`);document.getElementById('bookPractice').onclick=()=>{URL.revokeObjectURL(url);closeModal();state.view='practice';render();quiz()};document.getElementById('closeModal').onclick=()=>{URL.revokeObjectURL(url);closeModal()}}
function dataUrlToBlob(dataUrl){try{const [head,b64]=dataUrl.split(',');const bin=atob(b64);const bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);return new Blob([bytes],{type:(head.match(/data:([^;]+)/)||[])[1]||'application/pdf'})}catch{return null}}
async function saveBook(file){if(file.type!=='application/pdf'){showModal('<h2>PDF only</h2><p class="muted">Please choose a PDF textbook.</p>');return}if(file.size>200*1024*1024){showModal('<h2>File is too large</h2><p class="muted">For this browser-only version, please use a PDF smaller than 200 MB.</p>');return}const id=uid('bookfile');try{await putBookFile(id,file);state.books.unshift({id:uid('book'),fileId:id,name:file.name,size:(file.size/1024/1024).toFixed(1)+' MB',when:new Date().toLocaleDateString()});save();render();showModal(`<h2>Textbook added</h2><p class="muted"><strong>${esc(file.name)}</strong> is now saved privately in this browser and can be opened from the Textbooks tab.</p><button class="primary" id="openNow">Open textbook</button>`);document.getElementById('openNow').onclick=()=>openTextbook(0)}catch{showModal('<h2>Could not save textbook</h2><p class="muted">Your browser did not allow local file storage. Try again or use another browser.</p>')}}
function host(){const code=String(Math.floor(100000+Math.random()*900000));showModal(`<div class="eyebrow">HOST A GAME</div><h2>Campus Clash lobby</h2><p class="muted">Share this code with your classmates.</p><div class="card" style="margin-top:14px;text-align:center"><strong>Room code</strong><div style="font-size:38px;font-weight:800;letter-spacing:.12em;margin:8px 0">${code}</div><div class="muted">Waiting for players...</div></div><button class="primary" style="margin-top:14px" id="startHosted">Start demo round</button>`);document.getElementById('startHosted').onclick=()=>{closeModal();startGameSession(getQuestions(), 'Campus Clash')}}

function resetProgress(){state.progress={streak:0,xp:0,mastery:0,questionsAnswered:0,bestStreak:0,concepts:{}};state.courses=state.courses.map(c=>({...c,mastery:0,weak:'No study data yet'}));save();render()}
async function deleteAllStudyData(){for(const b of state.books)await deleteBookFile(b.fileId);state.courses=[];state.sets=[];state.books=[];state.progress={streak:0,xp:0,mastery:0,questionsAnswered:0,bestStreak:0,concepts:{}};state.settings={...structuredClone(seed.settings),name:'Student',avatar:'S',userId:state.settings.userId};save();render()}
function exportBackup(){const backup={format:'StudyHelper Backup',version:1,exportedAt:new Date().toISOString(),state:{...state,view:'dashboard',books:state.books.map(({data,...b})=>b)}};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`studyhelper-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const raw=JSON.parse(reader.result);const incoming=raw.state||raw;if(!incoming.courses||!incoming.sets||!incoming.progress)throw new Error('Invalid backup');state={...structuredClone(seed),...incoming,settings:{...structuredClone(seed.settings),...(incoming.settings||{})},progress:{...structuredClone(seed.progress),...(incoming.progress||{})},users:Array.isArray(incoming.users)?incoming.users:structuredClone(seed.users),view:'settings'};save();render();showModal('<h2>Backup restored</h2><p class="muted">Your StudyHelper data was restored. Textbook PDFs were not part of the JSON backup, so re-upload them if needed.</p>')}catch{showModal('<h2>Backup could not be imported</h2><p class="muted">That file does not look like a valid StudyHelper JSON backup.</p>')}};reader.readAsText(file)}
function bind(){const logoutBtn=document.getElementById('logoutButton');if(logoutBtn)logoutBtn.onclick=logout;const avatar=document.getElementById('profileAvatarButton');if(avatar){avatar.textContent=(state.settings.avatar||initials(state.settings.name)).slice(0,3).toUpperCase();avatar.onclick=showProfileEditor}document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>{if(!authReady)return;if(b.dataset.view==='admin'&&!isAdmin())return;state.view=b.dataset.view;save();render()});const adminNav=document.querySelector('.nav-item[data-view="admin"]');if(adminNav)adminNav.style.display=isAdmin()?'':'none';document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==='practice'){state.view='practice';render()}else if(a==='quiz')quiz();else if(a==='game'){state.view='games';render()}else if(a==='courses'){state.view='courses';render()}else if(a==='upload')document.getElementById('bookInput')?.click();else if(a==='host')host();else if(a==='edit-profile')showProfileEditor();else if(a==='settings'){state.view='settings';render()}else if(a==='admin'){state.view='admin';render()}else if(a==='new-user')showNewUser();else if(a==='export-data')exportBackup();else if(a==='reset-progress'){if(confirm('Reset XP, streaks, question counts, and mastery while keeping your courses and study sets?'))resetProgress()}else if(a==='delete-data'){if(confirm('Delete ALL courses, study sets, progress, and profile data from this browser? This cannot be undone unless you have a backup.'))deleteAllStudyData()}else if(a==='new-course')showNewCourse();else if(a==='new-set')showNewSet();else if(a==='course-pick')showModal(`<div class="eyebrow">QUESTION SOURCE</div><h2>Choose a saved set</h2><div class="grid grid-2" style="margin-top:14px">${state.sets.map(s=>`<button class="card" data-set="${s.id}" style="text-align:left"><strong>${esc(s.title)}</strong><div class="muted">${esc(courseById(s.courseId)?.name||'')}</div></button>`).join('')||'<div class="muted">No study sets yet.</div>'}</div>`)}) ;document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>{if(b.dataset.mode==='practice'){state.view='practice';render();quiz(null,'Apply');}else{state.view='games';render();startGameSession(getQuestions().filter(q=>q.courseId===b.dataset.course),'Recall')}});document.querySelectorAll('[data-game-mode]').forEach(b=>{b.onclick=()=>{const m=b.dataset.gameMode;const type=m==='Quest Rush'?'multiple':m==='Campus Clash'?'scramble':'multiple';startGameSession(getQuestions(),m,type)}});document.querySelectorAll('[data-set]').forEach(b=>b.onclick=()=>quiz(b.dataset.set));document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>quiz(null,'Focus',b.dataset.concept));document.querySelectorAll('[data-edit-set]').forEach(b=>b.onclick=()=>showNewSet(b.dataset.editSet));document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openTextbook(Number(b.dataset.book)));document.querySelectorAll('[data-remove-book]').forEach(b=>b.onclick=()=>{if(confirm('Remove this textbook from this browser?')){const idx=Number(b.dataset.removeBook);const book=state.books[idx];state.books.splice(idx,1);save();deleteBookFile(book?.fileId);render()}});const input=document.getElementById('bookInput');if(input)input.onchange=e=>{const f=e.target.files[0];if(f)saveBook(f)};const backupInput=document.getElementById('backupInput');if(backupInput)backupInput.onchange=e=>{const f=e.target.files[0];if(f)importBackup(f)};document.querySelectorAll('[data-request-approve]').forEach(b=>b.onclick=()=>handleRequestDecision(b.dataset.requestApprove,'approve'));document.querySelectorAll('[data-request-deny]').forEach(b=>b.onclick=()=>handleRequestDecision(b.dataset.requestDeny,'deny'));const rr=document.querySelector('[data-action="refresh-requests"]');if(rr)rr.onclick=refreshAdminData;document.querySelectorAll('[data-user-role]').forEach(b=>b.onclick=async()=>{if(!isAdmin())return;const u=state.users.find(x=>x.id===b.dataset.userRole);if(!u)return;try{if(authMode==='cloud'){const token=(await authClient.auth.getSession()).data.session?.access_token;const r=await fetch('/api/admin-manage-user',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({userId:u.id,action:'role',role:u.role==='admin'?'student':'admin'})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not change role.');Object.assign(u,d.user)}else{u.role=u.role==='admin'?'student':'admin'}save();render()}catch(e){alert(e.message)}});document.querySelectorAll('[data-user-status]').forEach(b=>b.onclick=async()=>{if(!isAdmin())return;const u=state.users.find(x=>x.id===b.dataset.userStatus);if(!u)return;try{if(authMode==='cloud'){const token=(await authClient.auth.getSession()).data.session?.access_token;const r=await fetch('/api/admin-manage-user',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({userId:u.id,action:'status',status:u.status==='disabled'?'active':'disabled'})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not change account status.');Object.assign(u,d.user)}else{u.status=u.status==='disabled'?'active':'disabled'}save();render()}catch(e){alert(e.message)}});document.querySelectorAll('[data-user-delete]').forEach(b=>b.onclick=async()=>{if(!isAdmin())return;const id=b.dataset.userDelete;if(!confirm('Delete this account permanently?'))return;try{if(authMode==='cloud'){const token=(await authClient.auth.getSession()).data.session?.access_token;const r=await fetch('/api/admin-manage-user',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({userId:id,action:'delete'})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Could not delete account.')}state.users=state.users.filter(u=>u.id!==id);save();render()}catch(e){alert(e.message)}});
const join=document.getElementById('joinBtn');if(join)join.onclick=()=>{showModal(`<h2>Game room</h2><p class="muted">This browser build can demonstrate a room flow, but realtime multiplayer requires the cloud backend.</p><button class="primary" id="enterRoom">Enter demo</button>`);document.getElementById('enterRoom').onclick=()=>{closeModal();quiz()}}}
document.getElementById('quickPractice').onclick=()=>{state.view='practice';render();quiz()};document.getElementById('closeModal').onclick=closeModal;document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')closeModal()};document.addEventListener('click',e=>{const set=e.target.closest('[data-set]');if(set&&document.getElementById('modal')?.classList.contains('hidden')===false){closeModal();quiz(set.dataset.set)} });bootAuth();
